"""HEARTAGRAM v1.2 · Sistema visual v2 "Noche editorial".

Reemplaza todo el CSS por un sistema nuevo basado en @layer:
tokens -> base -> layout -> components -> screens. Cero !important.
Conserva todos los id, data-action, data-screen y clases que usa el JS.
Nada se escribe hasta que todas las validaciones pasan.
"""
from pathlib import Path
from datetime import datetime, timezone
import json, re, shutil

ROOT = Path(__file__).resolve().parent
STAMP = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
BACKUP = ROOT / "data" / "ui_v2_backups" / f"ui-v2-{STAMP}"
VERSION = "ui2"

NEW_CSS = {
    "css/base.css": "/* Unlayered on purpose: these two rules must beat every layer. */\n[hidden] {\n  display: none;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    animation-duration: 0.01ms;\n    animation-iteration-count: 1;\n    transition-duration: 0.01ms;\n    scroll-behavior: auto;\n  }\n}\n\n@layer base {\n  *,\n  *::before,\n  *::after {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n  }\n\n  html {\n    -webkit-text-size-adjust: 100%;\n    background: var(--bg);\n  }\n\n  body {\n    min-width: 20rem;\n    min-height: 100dvh;\n    background:\n      radial-gradient(60rem 30rem at 0% -10%, var(--accent-glow), transparent 70%),\n      var(--bg);\n    background-attachment: fixed;\n    color: var(--text);\n    font: var(--fs-md) / 1.6 var(--font-sans);\n    -webkit-font-smoothing: antialiased;\n  }\n\n  img,\n  canvas,\n  svg {\n    display: block;\n    max-width: 100%;\n  }\n\n  button,\n  input,\n  select,\n  textarea {\n    font: inherit;\n    color: inherit;\n  }\n\n  button {\n    border: 0;\n    background: none;\n    cursor: pointer;\n    -webkit-tap-highlight-color: transparent;\n  }\n\n  ol,\n  ul {\n    list-style: none;\n  }\n\n  h1,\n  h2,\n  h3,\n  h4 {\n    font-weight: 400;\n    line-height: 1.15;\n    text-wrap: balance;\n  }\n\n  strong {\n    font-weight: 600;\n  }\n\n  a {\n    color: var(--accent-hover);\n  }\n\n  :focus-visible {\n    outline: 2px solid var(--accent);\n    outline-offset: 2px;\n  }\n\n  [tabindex=\"-1\"]:focus {\n    outline: none;\n  }\n\n  ::selection {\n    background: var(--accent);\n    color: var(--on-accent);\n  }\n\n  .noscript {\n    padding: var(--sp-8);\n    color: var(--text-muted);\n    text-align: center;\n  }\n}\n",
    "css/components.css": "/* Shared components. Screens only add layout, never restyle these. */\n@layer components {\n  /* ---------- Page header ---------- */\n  .home-header,\n  .discover-header,\n  .catalog-screen-header,\n  .collection-header {\n    display: grid;\n    gap: var(--sp-3);\n    max-width: 48rem;\n  }\n\n  /* ---------- Labels ---------- */\n  .home-label,\n  .discover-section-kicker,\n  .guide-kicker,\n  .eyebrow,\n  .npd-eyebrow,\n  .npd-label,\n  .catalog-field > span,\n  .gift-code-label,\n  .card-signal-meta,\n  .discover-mood-signal {\n    color: var(--text-faint);\n    font-size: var(--fs-xs);\n    font-weight: 600;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n  }\n\n  /* The single signature gesture: razor line + accent kicker. */\n  .home-kicker,\n  .discover-eyebrow,\n  .catalog-screen-kicker,\n  .collection-kicker,\n  .guide-hero > div > .guide-kicker,\n  .secondary-screen > .eyebrow {\n    display: inline-flex;\n    align-items: center;\n    gap: var(--sp-3);\n    color: var(--accent-hover);\n    font-size: var(--fs-xs);\n    font-weight: 600;\n    letter-spacing: 0.16em;\n    text-transform: uppercase;\n  }\n\n  .home-kicker::before,\n  .discover-eyebrow::before,\n  .catalog-screen-kicker::before,\n  .collection-kicker::before,\n  .guide-hero > div > .guide-kicker::before,\n  .secondary-screen > .eyebrow::before {\n    content: \"\";\n    width: 1.5rem;\n    height: 1px;\n    background: currentColor;\n  }\n\n  /* ---------- Titles and copy ---------- */\n  .home-title,\n  .discover-title,\n  .catalog-screen-title,\n  .collection-title,\n  .guide-title,\n  .secondary-screen > .title {\n    color: var(--text);\n    font-family: var(--font-display);\n    font-size: var(--fs-display);\n    font-weight: 400;\n    line-height: 1.05;\n    letter-spacing: -0.01em;\n  }\n\n  .home-subtitle,\n  .discover-lead,\n  .catalog-screen-lead,\n  .collection-lead,\n  .guide-lead,\n  .secondary-screen > .lead {\n    max-width: 60ch;\n    color: var(--text-muted);\n    font-size: var(--fs-lg);\n    line-height: 1.6;\n  }\n\n  .home-card-title,\n  .discover-section-title,\n  .discover-profile-title,\n  .wishlist-section-title,\n  .catalog-empty-title,\n  .collection-empty-title,\n  .getting-started-screen h3 {\n    color: var(--text);\n    font-family: var(--font-display);\n    font-size: var(--fs-2xl);\n    font-weight: 400;\n    line-height: 1.15;\n  }\n\n  .home-card-copy,\n  .discover-section-copy,\n  .wishlist-section-description,\n  .catalog-empty-copy,\n  .collection-empty-copy {\n    max-width: 60ch;\n    color: var(--text-muted);\n  }\n\n  .hint {\n    color: var(--text-faint);\n    font-size: var(--fs-sm);\n  }\n\n  /* ---------- Surfaces ---------- */\n  .home-empty-card,\n  .home-primary-card,\n  .home-panel,\n  .home-stat,\n  .discover-profile,\n  .card,\n  .discover-mood-card,\n  .catalog-wishlist-card,\n  .profile-copy,\n  .gift-slot,\n  .guide-progress,\n  .guide-card,\n  .guide-chapter,\n  .family-screen .steps li {\n    border: 1px solid var(--line);\n    border-radius: var(--r-lg);\n    background: var(--surface);\n  }\n\n  /* ---------- Buttons ---------- */\n  .btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: var(--sp-2);\n    min-height: 2.75rem;\n    padding: var(--sp-2) var(--sp-5);\n    border: 1px solid transparent;\n    border-radius: var(--r-md);\n    font-size: var(--fs-sm);\n    font-weight: 600;\n    line-height: 1.2;\n    text-align: center;\n    transition:\n      background var(--dur) var(--ease),\n      border-color var(--dur) var(--ease),\n      color var(--dur) var(--ease);\n  }\n\n  .btn:disabled {\n    opacity: 0.35;\n    cursor: not-allowed;\n  }\n\n  .btn-primary {\n    background: var(--accent);\n    color: var(--on-accent);\n  }\n\n  .btn-primary:hover:not(:disabled) {\n    background: var(--accent-hover);\n  }\n\n  .btn-ghost {\n    border-color: var(--line-strong);\n    background: var(--surface-2);\n    color: var(--text);\n  }\n\n  .btn-ghost:hover:not(:disabled) {\n    border-color: var(--text-faint);\n    background: var(--surface-3);\n  }\n\n  .btn-text {\n    min-height: 2.5rem;\n    padding: 0 var(--sp-2);\n    color: var(--text-muted);\n    font-weight: 500;\n  }\n\n  .btn-text:hover {\n    color: var(--text);\n    text-decoration: underline;\n    text-underline-offset: 4px;\n  }\n\n  /* ---------- Toggle buttons: Me interesa / Ya lo tengo ---------- */\n  .favorite-button,\n  .library-button {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: var(--sp-2);\n    min-height: 2.5rem;\n    padding: 0 var(--sp-4);\n    border: 1px solid var(--line-strong);\n    border-radius: var(--r-md);\n    background: transparent;\n    color: var(--text);\n    font-size: var(--fs-sm);\n    font-weight: 500;\n    transition:\n      background var(--dur) var(--ease),\n      border-color var(--dur) var(--ease),\n      color var(--dur) var(--ease);\n  }\n\n  .favorite-button:hover,\n  .library-button:hover {\n    border-color: var(--text-faint);\n    background: var(--surface-2);\n  }\n\n  .favorite-button[aria-pressed=\"true\"] {\n    border-color: var(--accent-line);\n    background: var(--accent-soft);\n    color: var(--accent-hover);\n  }\n\n  .library-button[aria-pressed=\"true\"] {\n    border-color: var(--gold-line);\n    background: var(--gold-soft);\n    color: var(--gold);\n  }\n\n  .library-button-remove {\n    color: var(--text-muted);\n  }\n\n  /* ---------- Chips ---------- */\n  .card-badges,\n  .npd-tags {\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-2);\n  }\n\n  .badge,\n  .npd-tag,\n  .catalog-detail-chip {\n    display: inline-flex;\n    align-items: center;\n    min-height: 1.5rem;\n    padding: 0 var(--sp-2);\n    border: 1px solid var(--line-strong);\n    border-radius: var(--r-pill);\n    color: var(--text-muted);\n    font-size: var(--fs-xs);\n    white-space: nowrap;\n  }\n\n  .card-owned,\n  .collection-owned-seal {\n    align-self: flex-start;\n    display: inline-flex;\n    align-items: center;\n    min-height: 1.5rem;\n    padding: 0 var(--sp-2);\n    border: 1px solid var(--gold-line);\n    border-radius: var(--r-pill);\n    background: var(--gold-soft);\n    color: var(--gold);\n    font-size: var(--fs-xs);\n    font-weight: 600;\n  }\n\n  .discover-mood-button,\n  .catalog-filter-chip {\n    display: inline-flex;\n    align-items: center;\n    gap: var(--sp-2);\n    min-height: 2.25rem;\n    padding: 0 var(--sp-4);\n    border: 1px solid var(--line-strong);\n    border-radius: var(--r-pill);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n    font-weight: 500;\n    transition:\n      background var(--dur) var(--ease),\n      border-color var(--dur) var(--ease),\n      color var(--dur) var(--ease);\n  }\n\n  .discover-mood-button:hover,\n  .catalog-filter-chip:hover {\n    border-color: var(--text-faint);\n    color: var(--text);\n  }\n\n  .discover-mood-button[aria-pressed=\"true\"] {\n    border-color: var(--accent-line);\n    background: var(--accent-soft);\n    color: var(--text);\n  }\n\n  .catalog-filter-chip::after {\n    content: \"×\";\n    color: var(--text-faint);\n  }\n\n  /* ---------- Form fields ---------- */\n  .catalog-field {\n    display: grid;\n    gap: var(--sp-2);\n    min-width: 0;\n  }\n\n  .catalog-field input,\n  .catalog-field select {\n    width: 100%;\n    min-height: 2.75rem;\n    padding: 0 var(--sp-3);\n    border: 1px solid var(--line-strong);\n    border-radius: var(--r-md);\n    background: var(--surface);\n    color: var(--text);\n    font-size: var(--fs-sm);\n  }\n\n  .catalog-field input::placeholder {\n    color: var(--text-faint);\n  }\n\n  .catalog-field input:focus-visible,\n  .catalog-field select:focus-visible {\n    border-color: var(--accent);\n    outline: 2px solid var(--accent-soft);\n    outline-offset: 0;\n  }\n\n  .catalog-field option {\n    background: var(--surface);\n    color: var(--text);\n  }\n\n  /* ---------- Status and empty states ---------- */\n  .catalog-status {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    gap: var(--sp-4);\n    padding: var(--sp-4) var(--sp-5);\n    border: 1px solid var(--line);\n    border-radius: var(--r-lg);\n    background: var(--surface);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .empty {\n    padding: var(--sp-6);\n    border: 1px dashed var(--line-strong);\n    border-radius: var(--r-lg);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n    text-align: center;\n  }\n\n  .catalog-empty-state,\n  .collection-empty-state {\n    display: grid;\n    grid-column: 1 / -1;\n    justify-items: center;\n    gap: var(--sp-3);\n    padding: var(--sp-12) var(--sp-6);\n    border: 1px dashed var(--line-strong);\n    border-radius: var(--r-xl);\n    text-align: center;\n  }\n\n  .catalog-empty-mark,\n  .collection-empty-mark {\n    color: var(--accent);\n    font-size: 1.5rem;\n    line-height: 1;\n  }\n\n  .catalog-empty-state .btn,\n  .collection-empty-state .btn {\n    margin-top: var(--sp-2);\n  }\n\n  /* ---------- Game card (curated recommendations) ---------- */\n  .card {\n    position: relative;\n    display: flex;\n    flex-direction: column;\n    gap: var(--sp-3);\n    min-width: 0;\n    padding: var(--sp-4);\n    transition: border-color var(--dur) var(--ease);\n  }\n\n  .card:hover {\n    border-color: var(--line-strong);\n  }\n\n  .card-sequence {\n    display: none;\n  }\n\n  .card-signal-art {\n    display: grid;\n    place-items: center;\n    aspect-ratio: 16 / 9;\n    overflow: hidden;\n    border-radius: var(--r-md);\n    background: var(--art);\n  }\n\n  .card-signal-initials {\n    color: rgb(255 255 255 / 0.55);\n    font: italic 2.5rem / 1 var(--font-display);\n  }\n\n  .card-title {\n    color: var(--text);\n    font: var(--fs-xl) / 1.2 var(--font-display);\n  }\n\n  .card-why {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n    line-height: 1.6;\n  }\n\n  .library-card-actions {\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-2);\n    margin-top: auto;\n    padding-top: var(--sp-2);\n  }\n\n  .card-hero {\n    padding: var(--sp-5);\n  }\n\n  .card-hero .card-signal-art {\n    aspect-ratio: 2 / 1;\n  }\n\n  .card-hero .card-signal-initials {\n    font-size: 4rem;\n  }\n\n  .card-hero .card-title {\n    font-size: clamp(1.75rem, 1.4rem + 1.5vw, 2.5rem);\n  }\n\n  .card-hero .card-why {\n    max-width: 60ch;\n    font-size: var(--fs-md);\n  }\n\n  .card-wildcard {\n    border-style: dashed;\n  }\n\n  @media (min-width: 40rem) {\n    .card-wildcard {\n      display: grid;\n      grid-template-columns: 14rem minmax(0, 1fr);\n      align-content: start;\n      gap: var(--sp-3) var(--sp-6);\n    }\n\n    .card-wildcard > * {\n      grid-column: 2;\n    }\n\n    .card-wildcard .card-signal-art {\n      grid-column: 1;\n      grid-row: 1 / span 6;\n      aspect-ratio: 3 / 4;\n    }\n  }\n\n  /* ---------- Cover fallback and skeletons ---------- */\n  .catalog-card-cover-fallback {\n    display: grid;\n    place-items: center;\n    width: 100%;\n    height: 100%;\n    background: var(--art);\n    color: rgb(255 255 255 / 0.55);\n    font: italic 2.5rem / 1 var(--font-display);\n  }\n\n  .catalog-card-skeleton {\n    display: grid;\n    gap: var(--sp-2);\n    pointer-events: none;\n  }\n\n  .catalog-skeleton-media,\n  .catalog-skeleton-line {\n    background: linear-gradient(90deg, var(--surface-2), var(--surface-3), var(--surface-2));\n    background-size: 200% 100%;\n    animation: skeleton 1.2s linear infinite;\n  }\n\n  .catalog-skeleton-media {\n    aspect-ratio: 3 / 4;\n    border-radius: var(--r-md);\n  }\n\n  .catalog-skeleton-line {\n    height: 0.75rem;\n    border-radius: var(--r-pill);\n  }\n\n  .catalog-skeleton-title {\n    width: 80%;\n  }\n\n  .catalog-skeleton-short {\n    width: 50%;\n  }\n\n  @keyframes skeleton {\n    to {\n      background-position: -200% 0;\n    }\n  }\n\n  /* ---------- Dialog: full screen on mobile, window from 40rem ---------- */\n  .catalog-dialog {\n    width: 100%;\n    max-width: none;\n    height: 100dvh;\n    max-height: none;\n    margin: 0;\n    padding: 0;\n    overflow: auto;\n    border: 0;\n    background: var(--surface);\n    color: var(--text);\n    overscroll-behavior: contain;\n  }\n\n  .catalog-dialog::backdrop {\n    background: rgb(0 0 0 / 0.72);\n    backdrop-filter: blur(6px);\n  }\n\n  .catalog-dialog-content {\n    position: relative;\n    padding: var(--sp-4) var(--sp-4) var(--sp-10);\n  }\n\n  .catalog-dialog-close {\n    position: sticky;\n    top: 0;\n    z-index: var(--z-sticky);\n    display: grid;\n    place-items: center;\n    width: 2.5rem;\n    height: 2.5rem;\n    margin-left: auto;\n    border: 1px solid var(--line-strong);\n    border-radius: var(--r-pill);\n    background: var(--surface-2);\n    color: var(--text);\n    font-size: 1.375rem;\n    line-height: 1;\n  }\n\n  .catalog-dialog-close:hover {\n    background: var(--surface-3);\n  }\n\n  @media (min-width: 40rem) {\n    .catalog-dialog {\n      width: min(64rem, 100vw - 2rem);\n      height: auto;\n      max-height: calc(100dvh - 2rem);\n      margin: auto;\n      border: 1px solid var(--line-strong);\n      border-radius: var(--r-xl);\n      box-shadow: var(--shadow-lg);\n    }\n\n    .catalog-dialog-content {\n      padding: var(--sp-6) var(--sp-10) var(--sp-10);\n    }\n  }\n}\n",
    "css/layout.css": "/* App shell: mobile bottom nav < 40rem · icon rail 40-64rem · sidebar >= 64rem */\n@layer layout {\n  .app-shell {\n    min-height: 100dvh;\n  }\n\n  #app {\n    min-height: 100dvh;\n    padding: var(--sp-6) var(--sp-4)\n      calc(var(--mobile-nav) + var(--sp-8) + env(safe-area-inset-bottom));\n  }\n\n  #app > .screen {\n    width: 100%;\n    max-width: var(--content-max);\n    margin-inline: auto;\n  }\n\n  .screen:not([hidden]) {\n    animation: screen-in 220ms var(--ease) both;\n  }\n\n  @keyframes screen-in {\n    from {\n      opacity: 0;\n      transform: translateY(6px);\n    }\n  }\n\n  /* Sidebar */\n  .app-sidebar {\n    display: none;\n  }\n\n  .app-sidebar-brand {\n    display: flex;\n    align-items: center;\n    gap: var(--sp-3);\n    min-height: 3rem;\n    margin-bottom: var(--sp-6);\n    padding: 0 var(--sp-2);\n  }\n\n  .app-sidebar-brand-mark {\n    display: grid;\n    place-items: center;\n    flex: none;\n    width: 2.25rem;\n    height: 2.25rem;\n    border: 1px solid var(--accent-line);\n    border-radius: var(--r-md);\n    color: var(--accent);\n    font: italic 1.25rem / 1 var(--font-display);\n  }\n\n  .app-sidebar-brand-subtitle {\n    color: var(--text);\n    font: 1.125rem / 1 var(--font-display);\n    white-space: nowrap;\n  }\n\n  .app-sidebar-nav,\n  .app-sidebar-secondary {\n    display: grid;\n    gap: var(--sp-1);\n  }\n\n  .app-sidebar-secondary {\n    margin-top: auto;\n    padding-top: var(--sp-4);\n    border-top: 1px solid var(--line);\n  }\n\n  .shell-nav-button,\n  .sidebar-toggle {\n    display: flex;\n    align-items: center;\n    gap: var(--sp-3);\n    width: 100%;\n    min-height: 2.75rem;\n    padding: 0 var(--sp-3);\n    border-radius: var(--r-md);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n    font-weight: 500;\n    text-align: left;\n    transition:\n      background var(--dur) var(--ease),\n      color var(--dur) var(--ease);\n  }\n\n  .shell-nav-button:hover:not(:disabled),\n  .sidebar-toggle:hover {\n    background: var(--surface-2);\n    color: var(--text);\n  }\n\n  .shell-nav-button[aria-current=\"page\"] {\n    background: var(--surface-3);\n    color: var(--text);\n  }\n\n  .shell-nav-button[aria-current=\"page\"] .shell-nav-icon {\n    color: var(--accent);\n  }\n\n  .shell-nav-button:disabled {\n    opacity: 0.35;\n    cursor: not-allowed;\n  }\n\n  .shell-nav-icon,\n  .mobile-nav-icon {\n    display: grid;\n    place-items: center;\n    flex: none;\n  }\n\n  .shell-nav-label,\n  .sidebar-toggle-label {\n    overflow: hidden;\n    white-space: nowrap;\n  }\n\n  .sidebar-toggle {\n    margin-top: var(--sp-2);\n  }\n\n  .visual-icon {\n    width: 1.25rem;\n    height: 1.25rem;\n    fill: none;\n    stroke: currentColor;\n    stroke-width: 1.6;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n  }\n\n  /* Mobile bottom navigation */\n  .mobile-navigation {\n    position: fixed;\n    inset: auto 0 0;\n    z-index: var(--z-nav);\n    display: grid;\n    grid-template-columns: repeat(4, minmax(0, 1fr));\n    min-height: var(--mobile-nav);\n    padding: var(--sp-1) var(--sp-2) max(var(--sp-1), env(safe-area-inset-bottom));\n    border-top: 1px solid var(--line);\n    background: rgb(10 8 10 / 0.92);\n    backdrop-filter: blur(16px);\n  }\n\n  .mobile-nav-button {\n    display: grid;\n    place-items: center;\n    align-content: center;\n    gap: 2px;\n    min-width: 0;\n    padding: var(--sp-1);\n    border-radius: var(--r-md);\n    color: var(--text-faint);\n    font-size: 0.6875rem;\n    font-weight: 500;\n  }\n\n  .mobile-nav-button[aria-current=\"page\"] {\n    color: var(--text);\n  }\n\n  .mobile-nav-button[aria-current=\"page\"] .mobile-nav-icon {\n    color: var(--accent);\n  }\n\n  .mobile-nav-button:disabled {\n    opacity: 0.35;\n  }\n\n  /* The quiz hides navigation so the question gets full attention. */\n  body.shell-focus-mode .app-sidebar,\n  body.shell-focus-mode .mobile-navigation {\n    display: none;\n  }\n\n  body.shell-focus-mode #app {\n    padding-bottom: var(--sp-8);\n  }\n\n  @media (min-width: 40rem) {\n    .mobile-navigation {\n      display: none;\n    }\n\n    .app-sidebar {\n      position: fixed;\n      inset: 0 auto 0 0;\n      z-index: var(--z-nav);\n      display: flex;\n      flex-direction: column;\n      width: var(--rail);\n      padding: var(--sp-4) var(--sp-3);\n      border-right: 1px solid var(--line);\n      background: var(--bg);\n    }\n\n    .app-sidebar-brand {\n      justify-content: center;\n      padding: 0;\n    }\n\n    .app-sidebar-brand-subtitle,\n    .shell-nav-label,\n    .sidebar-toggle {\n      display: none;\n    }\n\n    .shell-nav-button {\n      justify-content: center;\n      padding: 0;\n    }\n\n    #app {\n      padding: var(--sp-10) var(--sp-8) var(--sp-16) calc(var(--rail) + var(--sp-8));\n    }\n\n    body.shell-focus-mode #app {\n      padding-left: var(--sp-8);\n    }\n  }\n\n  @media (min-width: 64rem) {\n    .app-sidebar {\n      width: var(--sidebar);\n      padding: var(--sp-5) var(--sp-4);\n    }\n\n    .app-sidebar-brand {\n      justify-content: flex-start;\n      padding: 0 var(--sp-2);\n    }\n\n    .app-sidebar-brand-subtitle,\n    .shell-nav-label {\n      display: inline;\n    }\n\n    .sidebar-toggle {\n      display: flex;\n    }\n\n    .shell-nav-button {\n      justify-content: flex-start;\n      padding: 0 var(--sp-3);\n    }\n\n    #app {\n      padding-right: var(--sp-12);\n      padding-left: calc(var(--sidebar) + var(--sp-12));\n    }\n\n    body.sidebar-collapsed .app-sidebar {\n      width: var(--rail);\n      padding-inline: var(--sp-3);\n    }\n\n    body.sidebar-collapsed .app-sidebar-brand {\n      justify-content: center;\n      padding: 0;\n    }\n\n    body.sidebar-collapsed .app-sidebar-brand-subtitle,\n    body.sidebar-collapsed .shell-nav-label,\n    body.sidebar-collapsed .sidebar-toggle-label {\n      display: none;\n    }\n\n    body.sidebar-collapsed .shell-nav-button,\n    body.sidebar-collapsed .sidebar-toggle {\n      justify-content: center;\n      padding: 0;\n    }\n\n    body.sidebar-collapsed #app {\n      padding-left: calc(var(--rail) + var(--sp-12));\n    }\n\n    body.shell-focus-mode #app {\n      padding-left: var(--sp-12);\n    }\n  }\n}\n",
    "css/screens/catalog.css": "/* Explorar: covers carry the visual weight, the interface steps back. */\n@layer screens {\n  .catalog-screen {\n    display: grid;\n    gap: var(--sp-8);\n    align-content: start;\n  }\n\n  .catalog-screen #catalog-content {\n    display: grid;\n    gap: var(--sp-6);\n  }\n\n  .catalog-toolbar {\n    display: grid;\n    grid-template-columns: 1fr;\n    gap: var(--sp-3);\n  }\n\n  .catalog-summary {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    gap: var(--sp-3);\n    padding-bottom: var(--sp-4);\n    border-bottom: 1px solid var(--line);\n  }\n\n  #catalog-count {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .catalog-active-filters {\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-2);\n    margin-top: var(--sp-2);\n  }\n\n  .catalog-active-filters:empty {\n    display: none;\n  }\n\n  .catalog-grid {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: var(--sp-8) var(--sp-4);\n  }\n\n  .catalog-card {\n    display: flex;\n    flex-direction: column;\n    gap: var(--sp-3);\n    min-width: 0;\n  }\n\n  .catalog-card-open {\n    display: grid;\n    gap: var(--sp-3);\n    width: 100%;\n    border-radius: var(--r-md);\n    color: inherit;\n    text-align: left;\n  }\n\n  .catalog-card-media {\n    position: relative;\n    aspect-ratio: 3 / 4;\n    overflow: hidden;\n    border-radius: var(--r-md);\n    background: var(--surface-2);\n  }\n\n  .catalog-card-media::after {\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    border-radius: inherit;\n    box-shadow: inset 0 0 0 1px var(--line);\n    pointer-events: none;\n  }\n\n  .catalog-card-media img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    transition: transform 300ms var(--ease);\n  }\n\n  .catalog-card-open:hover .catalog-card-media img {\n    transform: scale(1.04);\n  }\n\n  .catalog-card-body {\n    display: grid;\n    gap: var(--sp-1);\n  }\n\n  .catalog-card-title {\n    display: -webkit-box;\n    overflow: hidden;\n    color: var(--text);\n    font-size: var(--fs-md);\n    font-weight: 600;\n    line-height: 1.35;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n  }\n\n  .catalog-card-meta {\n    color: var(--text-muted);\n    font-size: var(--fs-xs);\n  }\n\n  .catalog-card .card-badges {\n    margin-top: var(--sp-1);\n  }\n\n  /* Only the platform chip: genres live in the detail view. */\n  .catalog-card .badge:nth-child(n + 2) {\n    display: none;\n  }\n\n  .catalog-card-actions {\n    display: grid;\n    gap: var(--sp-2);\n  }\n\n  .catalog-card-actions button {\n    width: 100%;\n    min-height: 2.25rem;\n    padding: 0 var(--sp-2);\n    font-size: var(--fs-xs);\n  }\n\n  .catalog-pagination {\n    display: grid;\n    grid-template-columns: 1fr auto 1fr;\n    align-items: center;\n    gap: var(--sp-3);\n    padding-top: var(--sp-6);\n    border-top: 1px solid var(--line);\n  }\n\n  #catalog-previous {\n    justify-self: start;\n  }\n\n  #catalog-next {\n    justify-self: end;\n  }\n\n  .catalog-pagination .hint {\n    text-align: center;\n    white-space: nowrap;\n  }\n\n  @media (min-width: 40rem) {\n    .catalog-toolbar {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n\n    .catalog-search {\n      grid-column: 1 / -1;\n    }\n\n    .catalog-grid {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n    }\n  }\n\n  @media (min-width: 64rem) {\n    .catalog-toolbar {\n      grid-template-columns: minmax(0, 2fr) repeat(4, minmax(0, 1fr));\n    }\n\n    .catalog-search {\n      grid-column: auto;\n    }\n\n    .catalog-grid {\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n    }\n  }\n\n  @media (min-width: 80rem) {\n    .catalog-grid {\n      grid-template-columns: repeat(5, minmax(0, 1fr));\n    }\n  }\n}\n",
    "css/screens/collection.css": "/* Mi lista: Me interesa (accent) and Mi biblioteca (gold). */\n@layer screens {\n  .collection-screen {\n    display: grid;\n    gap: var(--sp-8);\n    align-content: start;\n  }\n\n  .collection-tabs {\n    display: inline-grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    justify-self: start;\n    gap: var(--sp-1);\n    padding: var(--sp-1);\n    border: 1px solid var(--line);\n    border-radius: var(--r-pill);\n    background: var(--surface);\n  }\n\n  .collection-tab {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: var(--sp-2);\n    min-height: 2.5rem;\n    padding: 0 var(--sp-5);\n    border-radius: var(--r-pill);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n    font-weight: 600;\n    white-space: nowrap;\n  }\n\n  .collection-tab:hover {\n    color: var(--text);\n  }\n\n  .collection-tab[aria-selected=\"true\"] {\n    background: var(--surface-3);\n    color: var(--text);\n  }\n\n  .collection-tab-count {\n    min-width: 1.5rem;\n    padding: 0 var(--sp-2);\n    border-radius: var(--r-pill);\n    background: var(--surface-2);\n    color: var(--text-muted);\n    font-size: var(--fs-xs);\n    line-height: 1.5rem;\n    text-align: center;\n  }\n\n  #collection-tab-interested[aria-selected=\"true\"] .collection-tab-count {\n    background: var(--accent);\n    color: var(--on-accent);\n  }\n\n  #collection-tab-owned[aria-selected=\"true\"] .collection-tab-count {\n    background: var(--gold);\n    color: var(--ink-950);\n  }\n\n  .wishlist-section,\n  .wishlist-group {\n    display: grid;\n    gap: var(--sp-6);\n  }\n\n  .wishlist-section-heading {\n    display: grid;\n    gap: var(--sp-1);\n  }\n\n  /* The tab already names the panel. */\n  .wishlist-section > .wishlist-section-heading .wishlist-section-title {\n    display: none;\n  }\n\n  .wishlist-group .wishlist-section-title {\n    font-size: var(--fs-xl);\n  }\n\n  .wishlist-section-description {\n    font-size: var(--fs-sm);\n  }\n\n  .wishlist-curated-list,\n  .catalog-wishlist-list {\n    display: grid;\n    gap: var(--sp-4);\n  }\n\n  .catalog-wishlist-card {\n    position: relative;\n    display: grid;\n    grid-template-columns: 6.5rem minmax(0, 1fr);\n    overflow: hidden;\n  }\n\n  .catalog-wishlist-media {\n    position: relative;\n    min-height: 9rem;\n    background: var(--surface-2);\n  }\n\n  .catalog-wishlist-media img {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  .catalog-wishlist-media .catalog-card-cover-fallback {\n    font: 600 var(--fs-xs) / 1.2 var(--font-sans);\n    text-align: center;\n  }\n\n  .catalog-wishlist-copy {\n    display: flex;\n    flex-direction: column;\n    gap: var(--sp-2);\n    min-width: 0;\n    padding: var(--sp-4);\n  }\n\n  .catalog-wishlist-title {\n    color: var(--text);\n    font-size: var(--fs-md);\n    font-weight: 600;\n    line-height: 1.3;\n  }\n\n  .catalog-wishlist-meta {\n    color: var(--text-muted);\n    font-size: var(--fs-xs);\n  }\n\n  .catalog-wishlist-actions {\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-2);\n    margin-top: auto;\n    padding-top: var(--sp-2);\n  }\n\n  .catalog-wishlist-actions > * {\n    min-height: 2.25rem;\n    padding: 0 var(--sp-3);\n    font-size: var(--fs-xs);\n  }\n\n  .collection-owned-seal {\n    position: absolute;\n    top: var(--sp-2);\n    left: var(--sp-2);\n    z-index: 1;\n    background: rgb(10 8 10 / 0.85);\n  }\n\n  .collection-panel-owned .card,\n  .collection-panel-owned .catalog-wishlist-card {\n    border-color: var(--gold-line);\n  }\n\n  .collection-actions {\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: space-between;\n    gap: var(--sp-3);\n    padding-top: var(--sp-6);\n    border-top: 1px solid var(--line);\n  }\n\n  .collection-screen[data-collection-active=\"owned\"] #collection-clear-interested {\n    display: none;\n  }\n\n  @media (min-width: 64rem) {\n    .wishlist-curated-list,\n    .catalog-wishlist-list {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n  }\n\n  @media (min-width: 80rem) {\n    .wishlist-curated-list,\n    .catalog-wishlist-list {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n    }\n  }\n}\n",
    "css/screens/discover.css": "@layer screens {\n  .discover-screen {\n    display: grid;\n    gap: var(--sp-12);\n    align-content: start;\n  }\n\n  .discover-profile {\n    display: grid;\n    gap: var(--sp-4);\n    padding: var(--sp-6);\n  }\n\n  .discover-profile-copy {\n    display: grid;\n    gap: var(--sp-2);\n  }\n\n  .discover-profile-subtitle {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .discover-profile .btn {\n    justify-self: start;\n  }\n\n  .discover-section,\n  .discover-section-heading {\n    display: grid;\n    gap: var(--sp-2);\n  }\n\n  .discover-section {\n    gap: var(--sp-5);\n  }\n\n  .discover-screen .card-list,\n  .discover-support-grid,\n  .discover-mood-results {\n    display: grid;\n    gap: var(--sp-4);\n  }\n\n  #list-for-you,\n  #list-out-of-zone {\n    grid-template-columns: 1fr;\n  }\n\n  .discover-moods {\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-2);\n  }\n\n  .discover-mood-card {\n    display: flex;\n    flex-direction: column;\n    gap: var(--sp-3);\n    padding: var(--sp-5);\n  }\n\n  .discover-mood-card h4 {\n    color: var(--text);\n    font: var(--fs-xl) / 1.2 var(--font-display);\n  }\n\n  .discover-mood-card p {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .discover-mood-card .favorite-button {\n    align-self: flex-start;\n    margin-top: auto;\n  }\n\n  @media (min-width: 40rem) {\n    .discover-profile {\n      grid-template-columns: minmax(0, 1fr) auto;\n      align-items: center;\n      padding: var(--sp-8);\n    }\n\n    .discover-screen .card-list,\n    .discover-support-grid,\n    .discover-mood-results {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n  }\n\n  @media (min-width: 64rem) {\n    #list-for-you {\n      grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);\n    }\n\n    .discover-support-grid {\n      grid-template-columns: 1fr;\n    }\n\n    #list-might-hook,\n    #list-duo,\n    .discover-mood-results {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n    }\n  }\n}\n",
    "css/screens/getting-started.css": "/* Inicia aqui: beginner-first checklist. */\n@layer screens {\n  #app > .getting-started-screen {\n    display: grid;\n    gap: var(--sp-10);\n    align-content: start;\n    max-width: 60rem;\n  }\n\n  .guide-hero {\n    display: grid;\n    gap: var(--sp-6);\n  }\n\n  .guide-hero > div:first-child {\n    display: grid;\n    gap: var(--sp-3);\n  }\n\n  .guide-progress {\n    display: grid;\n    gap: var(--sp-3);\n    padding: var(--sp-5);\n  }\n\n  .guide-track {\n    height: 6px;\n    overflow: hidden;\n    border-radius: var(--r-pill);\n    background: var(--line-strong);\n  }\n\n  .guide-bar {\n    width: 0;\n    height: 100%;\n    border-radius: inherit;\n    background: var(--accent);\n    transition: width 300ms var(--ease);\n  }\n\n  .guide-progress [data-guide-label] {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .is-complete .guide-progress {\n    border-color: var(--accent-line);\n  }\n\n  .getting-started-screen > section {\n    display: grid;\n    gap: var(--sp-4);\n  }\n\n  .guide-inventory {\n    display: grid;\n    gap: var(--sp-3);\n  }\n\n  .guide-card {\n    display: grid;\n    gap: var(--sp-1);\n    padding: var(--sp-4);\n  }\n\n  .guide-card strong,\n  .guide-note strong,\n  .guide-step strong {\n    color: var(--text);\n  }\n\n  .guide-card span {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .guide-note {\n    padding-left: var(--sp-4);\n    border-left: 2px solid var(--gold);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .guide-chapters {\n    display: grid;\n    gap: var(--sp-3);\n  }\n\n  .guide-chapter {\n    overflow: hidden;\n  }\n\n  .guide-chapter > summary {\n    display: grid;\n    grid-template-columns: auto minmax(0, 1fr) auto;\n    align-items: center;\n    gap: var(--sp-4);\n    padding: var(--sp-5);\n    cursor: pointer;\n    list-style: none;\n    transition: background var(--dur) var(--ease);\n  }\n\n  .guide-chapter > summary::-webkit-details-marker {\n    display: none;\n  }\n\n  .guide-chapter > summary:hover {\n    background: var(--surface-2);\n  }\n\n  .guide-chapter > summary::after {\n    content: \"+\";\n    color: var(--text-muted);\n    font-size: 1.5rem;\n    line-height: 1;\n  }\n\n  .guide-chapter[open] > summary::after {\n    content: \"−\";\n  }\n\n  .guide-number {\n    color: var(--accent-hover);\n    font: 600 var(--fs-sm) / 1 var(--font-mono);\n  }\n\n  .guide-chapter summary h3 {\n    font-size: var(--fs-xl);\n  }\n\n  .guide-chapter summary p {\n    margin-top: var(--sp-1);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .guide-body {\n    padding: 0 var(--sp-5) var(--sp-2);\n  }\n\n  .guide-step {\n    display: grid;\n    grid-template-columns: auto minmax(0, 1fr);\n    gap: var(--sp-3);\n    padding: var(--sp-4) 0;\n    border-top: 1px solid var(--line);\n    cursor: pointer;\n  }\n\n  .guide-step input {\n    width: 1.125rem;\n    height: 1.125rem;\n    margin-top: 0.2rem;\n    accent-color: var(--accent);\n  }\n\n  .guide-step p {\n    margin-top: var(--sp-1);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .guide-step:has(input:checked) strong {\n    color: var(--text-muted);\n    text-decoration: line-through;\n    text-decoration-color: var(--accent);\n  }\n\n  .guide-footer,\n  .guide-footer > div {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: var(--sp-3);\n  }\n\n  .guide-footer {\n    justify-content: space-between;\n  }\n\n  @media (min-width: 40rem) {\n    .guide-inventory {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n    }\n  }\n\n  @media (min-width: 64rem) {\n    .guide-hero {\n      grid-template-columns: minmax(0, 1fr) 18rem;\n      align-items: end;\n    }\n  }\n}\n",
    "css/screens/home.css": "@layer screens {\n  .home-screen {\n    display: grid;\n    gap: var(--sp-10);\n    align-content: start;\n  }\n\n  .home-header {\n    padding-top: var(--sp-4);\n  }\n\n  .home-title {\n    font-size: var(--fs-hero);\n    font-style: italic;\n    line-height: 0.95;\n  }\n\n  .home-empty-card,\n  .home-primary-card {\n    display: grid;\n    gap: var(--sp-4);\n    padding: var(--sp-8) var(--sp-6);\n    border-color: var(--line-strong);\n    background:\n      radial-gradient(40rem 20rem at 100% 0%, var(--accent-glow), transparent 60%),\n      var(--surface);\n  }\n\n  .home-primary-copy {\n    display: grid;\n    gap: var(--sp-3);\n  }\n\n  .home-secondary-actions,\n  .home-panel-actions {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: var(--sp-3);\n  }\n\n  .home-empty-card .home-secondary-actions {\n    margin-top: var(--sp-2);\n  }\n\n  #home-returning-state {\n    display: grid;\n    gap: var(--sp-6);\n  }\n\n  .home-primary-card .btn {\n    justify-self: start;\n  }\n\n  .home-grid {\n    display: grid;\n    gap: var(--sp-4);\n  }\n\n  .home-panel {\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n    gap: var(--sp-6);\n    padding: var(--sp-6);\n  }\n\n  .home-panel > div:first-child {\n    display: grid;\n    gap: var(--sp-2);\n  }\n\n  .home-panel .home-card-title {\n    font-size: var(--fs-xl);\n  }\n\n  #home-space-title {\n    margin-bottom: var(--sp-3);\n  }\n\n  .home-stats {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n    gap: var(--sp-3);\n  }\n\n  .home-stat {\n    display: grid;\n    gap: var(--sp-1);\n    padding: var(--sp-4);\n    text-align: left;\n    transition:\n      background var(--dur) var(--ease),\n      border-color var(--dur) var(--ease);\n  }\n\n  .home-stat:hover {\n    border-color: var(--line-strong);\n    background: var(--surface-2);\n  }\n\n  .home-stat-value {\n    color: var(--text);\n    font: 2rem / 1 var(--font-display);\n  }\n\n  .home-stat-label {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n    line-height: 1.3;\n  }\n\n  @media (min-width: 40rem) {\n    .home-empty-card,\n    .home-primary-card {\n      padding: var(--sp-10);\n    }\n\n    .home-grid {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n  }\n\n  @media (min-width: 64rem) {\n    .home-primary-card {\n      grid-template-columns: minmax(0, 1fr) auto;\n      align-items: end;\n    }\n  }\n}\n",
    "css/screens/nintendo-product-detail.css": "/* Editorial product detail inside #catalog-dialog. */\n@layer screens {\n  #nintendo-product-detail {\n    display: block;\n  }\n\n  .npd {\n    display: grid;\n    gap: var(--sp-10);\n  }\n\n  .npd-hero {\n    display: grid;\n    gap: var(--sp-6);\n  }\n\n  .npd-cover {\n    position: relative;\n    width: min(100%, 16rem);\n    aspect-ratio: 3 / 4;\n    overflow: hidden;\n    border-radius: var(--r-lg);\n    background: var(--surface-2);\n    box-shadow: var(--shadow-lg);\n  }\n\n  .npd-cover img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  .npd-hero-copy {\n    display: grid;\n    align-content: start;\n    gap: var(--sp-4);\n  }\n\n  .npd-title {\n    color: var(--text);\n    font: 400 clamp(2rem, 1.5rem + 2vw, 3.25rem) / 1.05 var(--font-display);\n  }\n\n  .npd-price {\n    display: grid;\n    gap: var(--sp-1);\n  }\n\n  .npd-price strong {\n    color: var(--text);\n    font-size: var(--fs-2xl);\n    font-weight: 600;\n  }\n\n  .npd-before {\n    color: var(--text-faint);\n    font-size: var(--fs-sm);\n    text-decoration: line-through;\n  }\n\n  .npd-actions {\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-3);\n  }\n\n  .npd-action {\n    flex: 1 1 11rem;\n  }\n\n  .npd-section {\n    display: grid;\n    gap: var(--sp-4);\n  }\n\n  .npd-heading {\n    padding-bottom: var(--sp-3);\n    border-bottom: 1px solid var(--line);\n    color: var(--text-faint);\n    font-size: var(--fs-xs);\n    font-weight: 600;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n  }\n\n  .npd-overview p {\n    max-width: 65ch;\n    color: var(--text-muted);\n    font-size: var(--fs-lg);\n    line-height: 1.7;\n  }\n\n  .npd-facts {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: var(--sp-5) var(--sp-4);\n  }\n\n  .npd-value {\n    margin-top: var(--sp-1);\n    color: var(--text);\n  }\n\n  .npd-help,\n  .npd-copy {\n    margin-top: var(--sp-1);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .npd-explainers {\n    display: grid;\n    gap: var(--sp-3);\n  }\n\n  .npd-explainer,\n  .npd-rating {\n    padding: var(--sp-4);\n    border: 1px solid var(--line);\n    border-radius: var(--r-md);\n    background: var(--surface-2);\n  }\n\n  .npd-explainer h4 {\n    font-size: var(--fs-sm);\n    font-weight: 600;\n  }\n\n  .npd-explainer p {\n    margin-top: var(--sp-1);\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .npd-explainer small {\n    display: block;\n    margin-top: var(--sp-2);\n    color: var(--text-faint);\n  }\n\n  .npd-rating {\n    border-color: var(--gold-line);\n  }\n\n  .npd-rating .npd-heading {\n    padding: 0;\n    border: 0;\n    color: var(--gold);\n  }\n\n  .npd-rating-lead {\n    color: var(--text);\n    font-weight: 600;\n  }\n\n  .npd-gallery-head {\n    display: flex;\n    align-items: end;\n    justify-content: space-between;\n    gap: var(--sp-3);\n    border-bottom: 1px solid var(--line);\n  }\n\n  .npd-gallery-head .npd-heading {\n    border: 0;\n  }\n\n  .npd-counter {\n    padding-bottom: var(--sp-3);\n    color: var(--text-faint);\n    font: var(--fs-xs) / 1 var(--font-mono);\n  }\n\n  .npd-featured {\n    width: 100%;\n    max-height: 36rem;\n    border-radius: var(--r-lg);\n    background: var(--ink-950);\n    object-fit: contain;\n  }\n\n  .npd-thumbs {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(5rem, 1fr));\n    gap: var(--sp-2);\n  }\n\n  .npd-thumb {\n    aspect-ratio: 16 / 10;\n    overflow: hidden;\n    border: 2px solid transparent;\n    border-radius: var(--r-sm);\n    opacity: 0.55;\n    transition: opacity var(--dur) var(--ease);\n  }\n\n  .npd-thumb:hover {\n    opacity: 0.85;\n  }\n\n  .npd-thumb[aria-current=\"true\"] {\n    border-color: var(--accent);\n    opacity: 1;\n  }\n\n  .npd-thumb img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  @media (min-width: 40rem) {\n    .npd-hero {\n      grid-template-columns: minmax(11rem, 16rem) minmax(0, 1fr);\n      align-items: start;\n      gap: var(--sp-8);\n    }\n\n    .npd-explainers {\n      grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));\n    }\n  }\n\n  @media (min-width: 64rem) {\n    .npd-facts {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n    }\n  }\n}\n",
    "css/screens/profile.css": "/* Perfil: copy and radar side by side on desktop. Loads after secondary.css. */\n@layer screens {\n  #app > .profile-screen {\n    grid-template-areas:\n      \"eyebrow\"\n      \"title\"\n      \"subtitle\"\n      \"radar\"\n      \"copy\"\n      \"traits\"\n      \"note\"\n      \"actions\";\n    gap: var(--sp-4);\n    align-items: start;\n    max-width: var(--content-max);\n  }\n\n  .profile-screen > .eyebrow {\n    grid-area: eyebrow;\n  }\n\n  .profile-title {\n    grid-area: title;\n  }\n\n  .profile-subtitle {\n    grid-area: subtitle;\n    color: var(--text-muted);\n  }\n\n  .profile-copy {\n    grid-area: copy;\n    display: grid;\n    gap: var(--sp-3);\n    padding: var(--sp-6);\n  }\n\n  .profile-summary {\n    color: var(--text);\n    font: var(--fs-xl) / 1.35 var(--font-display);\n  }\n\n  .profile-body {\n    color: var(--text-muted);\n    line-height: 1.7;\n  }\n\n  .profile-radar {\n    grid-area: radar;\n    justify-self: center;\n    width: min(100%, 20rem);\n    height: auto;\n  }\n\n  .profile-traits {\n    grid-area: traits;\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: var(--sp-3);\n    margin-top: var(--sp-4);\n  }\n\n  .profile-trait {\n    display: grid;\n    gap: var(--sp-2);\n    padding: var(--sp-3) var(--sp-4);\n    border: 1px solid var(--line);\n    border-radius: var(--r-md);\n    background: var(--surface);\n  }\n\n  .profile-trait-head {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: var(--sp-2);\n  }\n\n  .profile-trait-label {\n    font-size: var(--fs-sm);\n  }\n\n  .profile-trait-value {\n    color: var(--accent-hover);\n    font-size: var(--fs-xs);\n    font-weight: 600;\n    letter-spacing: 0.08em;\n  }\n\n  .profile-trait-track {\n    height: 4px;\n    overflow: hidden;\n    border-radius: var(--r-pill);\n    background: var(--line-strong);\n  }\n\n  .profile-trait-fill {\n    height: 100%;\n    border-radius: inherit;\n    background: var(--accent);\n  }\n\n  .profile-flex-note {\n    grid-area: note;\n    max-width: 65ch;\n    color: var(--text-faint);\n    font-size: var(--fs-sm);\n  }\n\n  .profile-actions {\n    grid-area: actions;\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-3);\n  }\n\n  .profile-actions .btn-primary {\n    order: -1;\n  }\n\n  @media (min-width: 64rem) {\n    #app > .profile-screen {\n      grid-template-columns: minmax(0, 1fr) 20rem;\n      grid-template-areas:\n        \"eyebrow radar\"\n        \"title radar\"\n        \"subtitle radar\"\n        \"copy radar\"\n        \"traits traits\"\n        \"note note\"\n        \"actions actions\";\n      column-gap: var(--sp-12);\n    }\n\n    .profile-radar {\n      align-self: center;\n    }\n\n    .profile-traits {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n    }\n  }\n}\n",
    "css/screens/quiz.css": "@layer screens {\n  #app > .screen[data-screen=\"quiz\"] {\n    display: grid;\n    align-content: center;\n    gap: var(--sp-6);\n    max-width: var(--reading-max);\n    min-height: calc(100dvh - var(--sp-16));\n  }\n\n  .quiz-progress {\n    height: 4px;\n    overflow: hidden;\n    border-radius: var(--r-pill);\n    background: var(--line-strong);\n  }\n\n  .quiz-progress-bar {\n    width: 0;\n    height: 100%;\n    border-radius: inherit;\n    background: var(--accent);\n    transition: width 300ms var(--ease);\n  }\n\n  .quiz-question {\n    color: var(--text);\n    font: 400 clamp(1.75rem, 1.3rem + 2vw, 2.75rem) / 1.15 var(--font-display);\n  }\n\n  .quiz-options {\n    display: grid;\n    gap: var(--sp-3);\n  }\n\n  .quiz-option {\n    display: grid;\n    grid-template-columns: 2rem minmax(0, 1fr);\n    align-items: center;\n    gap: var(--sp-4);\n    min-height: 4rem;\n    padding: var(--sp-3) var(--sp-4);\n    border: 1px solid var(--line-strong);\n    border-radius: var(--r-lg);\n    background: var(--surface);\n    color: var(--text);\n    line-height: 1.45;\n    text-align: left;\n    transition:\n      background var(--dur) var(--ease),\n      border-color var(--dur) var(--ease);\n  }\n\n  .quiz-option:hover {\n    border-color: var(--text-faint);\n    background: var(--surface-2);\n  }\n\n  .quiz-option[aria-checked=\"true\"] {\n    border-color: var(--accent);\n    background: var(--accent-soft);\n  }\n\n  .quiz-option-index {\n    display: grid;\n    place-items: center;\n    width: 2rem;\n    height: 2rem;\n    border: 1px solid var(--line-strong);\n    border-radius: var(--r-pill);\n    color: var(--text-muted);\n    font-size: var(--fs-xs);\n    font-weight: 600;\n  }\n\n  .quiz-option[aria-checked=\"true\"] .quiz-option-index {\n    border-color: var(--accent);\n    background: var(--accent);\n    color: var(--on-accent);\n  }\n\n  .screen[data-screen=\"quiz\"] > [data-action=\"back\"] {\n    justify-self: start;\n  }\n\n  @media (min-width: 40rem) {\n    .quiz-options {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n  }\n}\n",
    "css/screens/secondary.css": "/* Mi regalo and grupo familiar. Profile builds on this in profile.css. */\n@layer screens {\n  #app > .secondary-screen {\n    display: grid;\n    gap: var(--sp-6);\n    align-content: start;\n    max-width: 52rem;\n  }\n\n  .gift-slot {\n    display: grid;\n    gap: var(--sp-4);\n    padding: var(--sp-6);\n  }\n\n  .gift-slot > .lead {\n    color: var(--text);\n    font: var(--fs-xl) / 1.35 var(--font-display);\n  }\n\n  .gift-slot > p:not(.lead):not(.hint) {\n    color: var(--text-muted);\n  }\n\n  .gift-code-list {\n    display: grid;\n    gap: var(--sp-3);\n  }\n\n  .gift-code-card {\n    display: grid;\n    gap: var(--sp-2);\n    padding: var(--sp-4);\n    border: 1px dashed var(--line-strong);\n    border-radius: var(--r-md);\n    background: var(--surface-2);\n  }\n\n  .gift-code-mask {\n    color: var(--text);\n    font: 500 var(--fs-lg) / 1.3 var(--font-mono);\n    letter-spacing: 0.06em;\n    overflow-wrap: anywhere;\n  }\n\n  .redeem-guide {\n    padding: var(--sp-4);\n    border: 1px solid var(--line);\n    border-radius: var(--r-md);\n  }\n\n  .redeem-guide summary {\n    font-weight: 600;\n    cursor: pointer;\n  }\n\n  .redeem-guide[open] summary {\n    margin-bottom: var(--sp-3);\n  }\n\n  .redeem-steps {\n    display: grid;\n    gap: var(--sp-2);\n    padding-left: var(--sp-5);\n    color: var(--text-muted);\n    list-style: decimal;\n  }\n\n  .redeem-steps li::marker {\n    color: var(--accent-hover);\n  }\n\n  .redeem-guide .hint {\n    margin-top: var(--sp-3);\n  }\n\n  .gift-actions {\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--sp-3);\n  }\n\n  .family-screen .steps {\n    display: grid;\n    gap: var(--sp-3);\n    counter-reset: family-step;\n  }\n\n  .family-screen .steps li {\n    display: grid;\n    gap: var(--sp-1);\n    padding: var(--sp-5);\n    counter-increment: family-step;\n  }\n\n  .family-screen .steps li::before {\n    content: counter(family-step, decimal-leading-zero);\n    margin-bottom: var(--sp-2);\n    color: var(--accent-hover);\n    font-size: var(--fs-xs);\n    font-weight: 600;\n    letter-spacing: 0.1em;\n  }\n\n  .family-screen .steps strong {\n    color: var(--text);\n  }\n\n  .family-screen .steps span {\n    color: var(--text-muted);\n    font-size: var(--fs-sm);\n  }\n\n  .family-screen > .btn {\n    justify-self: start;\n  }\n\n  @media (min-width: 40rem) {\n    .gift-slot {\n      padding: var(--sp-8);\n    }\n\n    .gift-code-list,\n    .family-screen .steps {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n  }\n}\n",
    "css/tokens.css": "/* HEARTAGRAM · Visual System v2 · \"Noche editorial\"\n   Cascade order is declared once here. Later layers always win,\n   so the system needs no override flags. */\n@layer base, layout, components, screens;\n\n:root {\n  color-scheme: dark;\n\n  /* Palette */\n  --ink-950: #0a080a;\n  --ink-900: #121012;\n  --ink-850: #181418;\n  --ink-800: #201a1f;\n  --text: #f4eef1;\n  --text-muted: #a99ba2;\n  --text-faint: #786b71;\n  --line: rgb(255 255 255 / 0.08);\n  --line-strong: rgb(255 255 255 / 0.16);\n  --accent: #e24a85;\n  --accent-hover: #ef6a9d;\n  --accent-soft: rgb(226 74 133 / 0.14);\n  --accent-line: rgb(226 74 133 / 0.45);\n  --accent-glow: rgb(226 74 133 / 0.16);\n  --gold: #cfa968;\n  --gold-soft: rgb(207 169 104 / 0.12);\n  --gold-line: rgb(207 169 104 / 0.38);\n  --on-accent: #ffffff;\n\n  /* Surfaces */\n  --bg: var(--ink-950);\n  --surface: var(--ink-900);\n  --surface-2: var(--ink-850);\n  --surface-3: var(--ink-800);\n  --art: radial-gradient(120% 120% at 0% 0%, rgb(226 74 133 / 0.3), transparent 55%),\n    linear-gradient(160deg, var(--ink-800), var(--ink-950));\n\n  /* Read by js/ui.js to draw the profile radar */\n  --color-border: rgb(255 255 255 / 0.12);\n  --color-text-muted: var(--text-muted);\n  --color-accent-strong: var(--accent);\n\n  /* Type: serif for display only, sans for everything else */\n  --font-sans: system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  --font-display: \"Iowan Old Style\", \"Palatino Linotype\", \"Book Antiqua\", Palatino, Georgia, serif;\n  --font-mono: ui-monospace, \"Cascadia Mono\", Consolas, monospace;\n  --fs-xs: 0.75rem;\n  --fs-sm: 0.875rem;\n  --fs-md: 1rem;\n  --fs-lg: 1.125rem;\n  --fs-xl: 1.375rem;\n  --fs-2xl: 1.75rem;\n  --fs-display: clamp(2.25rem, 1.6rem + 2.6vw, 3.5rem);\n  --fs-hero: clamp(3rem, 2rem + 5vw, 5.5rem);\n\n  /* Space: 4px base */\n  --sp-1: 0.25rem;\n  --sp-2: 0.5rem;\n  --sp-3: 0.75rem;\n  --sp-4: 1rem;\n  --sp-5: 1.25rem;\n  --sp-6: 1.5rem;\n  --sp-8: 2rem;\n  --sp-10: 2.5rem;\n  --sp-12: 3rem;\n  --sp-16: 4rem;\n\n  /* Shape */\n  --r-sm: 6px;\n  --r-md: 10px;\n  --r-lg: 14px;\n  --r-xl: 20px;\n  --r-pill: 999px;\n\n  /* Layout. Breakpoints (not tokenizable in @media): 40rem · 64rem · 80rem */\n  --content-max: 72rem;\n  --reading-max: 44rem;\n  --sidebar: 15rem;\n  --rail: 4.5rem;\n  --mobile-nav: 4.25rem;\n  --z-sticky: 5;\n  --z-nav: 50;\n\n  /* Motion and depth */\n  --ease: cubic-bezier(0.2, 0, 0, 1);\n  --dur: 160ms;\n  --shadow-lg: 0 24px 64px rgb(0 0 0 / 0.5);\n}\n"
}

ORDER = [
    "css/tokens.css", "css/base.css", "css/layout.css", "css/components.css",
    "css/screens/home.css", "css/screens/quiz.css", "css/screens/discover.css",
    "css/screens/catalog.css", "css/screens/nintendo-product-detail.css",
    "css/screens/collection.css", "css/screens/getting-started.css",
    "css/screens/secondary.css", "css/screens/profile.css",
]
DELETE = [
    "css/theme.css", "css/theme-romance.css", "css/reset.css",
    "css/shell.css", "css/visual-system.css", "js/visual-system.js",
]
QA = "import assert from \"node:assert/strict\";\nimport { readFileSync, readdirSync, existsSync, statSync } from \"node:fs\";\nimport { join } from \"node:path\";\n\nconst VERSION = \"ui2\";\nconst EXPECTED = [\n  \"css/tokens.css\",\n  \"css/base.css\",\n  \"css/layout.css\",\n  \"css/components.css\",\n  \"css/screens/home.css\",\n  \"css/screens/quiz.css\",\n  \"css/screens/discover.css\",\n  \"css/screens/catalog.css\",\n  \"css/screens/nintendo-product-detail.css\",\n  \"css/screens/collection.css\",\n  \"css/screens/getting-started.css\",\n  \"css/screens/secondary.css\",\n  \"css/screens/profile.css\",\n];\n\nconst walk = (dir) => readdirSync(dir).flatMap((name) => {\n  const path = join(dir, name);\n  return statSync(path).isDirectory() ? walk(path) : [path];\n});\nconst strip = (text) => text.replace(/\\/\\*[\\s\\S]*?\\*\\//g, \"\");\nconst html = readFileSync(\"index.html\", \"utf8\");\n\nconst links = [...html.matchAll(/<link rel=\"stylesheet\" href=\"([^\"?]+)\\?v=([^\"]+)\"/g)];\nassert.deepEqual(links.map(([, path]) => path), EXPECTED, \"Orden de hojas CSS inesperado\");\nlinks.forEach(([, path, version]) => {\n  assert.equal(existsSync(path), true, `${path} no existe`);\n  assert.equal(version, VERSION, `${path} no usa ?v=${VERSION}`);\n});\nconsole.log(`[OK] ${links.length} hojas CSS en orden y con ?v=${VERSION}`);\n\nconst onDisk = walk(\"css\").filter((path) => path.endsWith(\".css\")).map((path) => path.replaceAll(\"\\\\\", \"/\"));\nconst orphans = onDisk.filter((path) => !EXPECTED.includes(path));\nassert.deepEqual(orphans, [], `Hojas CSS sin cargar: ${orphans.join(\", \")}`);\nconsole.log(\"[OK] Sin hojas CSS huérfanas\");\n\nconst files = EXPECTED.map((path) => strip(readFileSync(path, \"utf8\")));\nconst css = files.join(\"\\n\");\nassert.match(files[0], /^\\s*@layer base, layout, components, screens;/, \"tokens.css debe declarar las capas primero\");\nconsole.log(\"[OK] Capas de cascada declaradas en tokens.css\");\n\nconst defined = new Set([...css.matchAll(/(--[\\w-]+)\\s*:/g)].map((m) => m[1]));\nconst used = new Set([...css.matchAll(/var\\(\\s*(--[\\w-]+)/g)].map((m) => m[1]));\nconst undefinedVars = [...used].filter((name) => !defined.has(name));\nassert.deepEqual(undefinedVars, [], `Variables sin definir: ${undefinedVars.join(\", \")}`);\nfor (const token of [\"--color-border\", \"--color-text-muted\", \"--color-accent-strong\"]) {\n  assert.ok(defined.has(token), `${token} lo usa el radar de js/ui.js`);\n}\nconsole.log(\"[OK] Variables definidas, incluidas las del radar\");\n\nassert.equal((css.match(/!important/g) || []).length, 0, \"El sistema v2 no usa !important\");\nconsole.log(\"[OK] 0 !important\");\n\nfor (const legacy of [\".app-navigation\", \".assistant-\", \"has-app-navigation\", \".grain\"]) {\n  assert.equal(css.includes(legacy), false, `Selector heredado: ${legacy}`);\n}\nassert.equal(/\\.visual-(?!icon)/.test(css), false, \"Selector heredado: .visual-*\");\nassert.equal(html.includes(\"visual-system\"), false, \"index.html aún carga visual-system\");\nassert.equal(existsSync(\"js/visual-system.js\"), false, \"js/visual-system.js debe eliminarse\");\nconsole.log(\"[OK] Sin capas visuales heredadas\");\n\nconsole.log(\"\\n[OK] QA de higiene CSS completo\");\n"

def stop(msg): raise SystemExit(f"[FAIL] {msg}")

def read(rel):
    p = ROOT / rel
    if not p.is_file(): stop(f"No se encontró {rel}")
    return p.read_text(encoding="utf-8-sig").replace("\r\n", "\n")

def replace_once(text, old, new, label):
    n = text.count(old)
    if n != 1: stop(f"{label}: se esperaba 1 coincidencia y hubo {n}")
    return text.replace(old, new, 1)

def plan():
    out = {}

    h = read("index.html")
    h, n = re.subn(r'^[ \t]*<link rel="stylesheet"[^>]*>[ \t]*\n', "", h, flags=re.M)
    if n != 16: stop(f"index.html: se esperaban 16 hojas CSS y hubo {n}")
    h, n = re.subn(r'^[ \t]*<script type="module" src="js/visual-system\.js[^"]*"></script>[ \t]*\n', "", h, flags=re.M)
    if n != 1: stop(f"index.html: script visual-system.js encontrado {n} veces")
    h, n = re.subn(r'^[ \t]*<div class="grain" aria-hidden="true"></div>[ \t]*\n', "", h, flags=re.M)
    if n != 1: stop(f"index.html: div.grain encontrado {n} veces")
    links = "".join(f'    <link rel="stylesheet" href="{p}?v={VERSION}" />\n' for p in ORDER)
    h = replace_once(h, "</head>", links + "  </head>", "index.html </head>")
    out["index.html"] = h

    ui = read("js/ui.js")
    ui = replace_once(ui,
        '`⟦ SIGNAL ${String(current).padStart(2, "0")} / ${String(total).padStart(2, "0")} ⟧`',
        '`Pregunta ${current} de ${total}`', "ui.js contador")
    ui = replace_once(ui, '`Señal ${current} de ${total}`', '`Pregunta ${current} de ${total}`', "ui.js aria-valuetext")
    ui = replace_once(ui, '`${primary.subtitle} // señal secundaria: ${secondary.title}`',
        '`${primary.subtitle} · También: ${secondary.title}`', "ui.js subtítulo de perfil")
    out["js/ui.js"] = ui

    d = read("js/discover-ui.js")
    d = replace_once(d, '`Señal secundaria // ${names.secondary}`', '`También: ${names.secondary}`', "discover-ui.js")
    out["js/discover-ui.js"] = d

    c = read("js/catalog-ui.js")
    c = replace_once(c, '"Sin señales con esos filtros"', '"Sin resultados con esos filtros"', "catalog-ui.js")
    out["js/catalog-ui.js"] = c

    gi = read(".gitignore")
    if "data/ui_v2_backups/" not in gi: gi = gi.rstrip("\n") + "\ndata/ui_v2_backups/\n"
    out[".gitignore"] = gi

    for rel in DELETE:
        if not (ROOT / rel).is_file(): stop(f"No se encontró {rel} para eliminar")
    return out

def main():
    edits = plan()
    BACKUP.mkdir(parents=True, exist_ok=True)
    shutil.copytree(ROOT / "css", BACKUP / "css")
    for rel in list(edits) + ["js/visual-system.js", "tests/css-hygiene-qa.mjs"]:
        src = ROOT / rel
        if src.is_file():
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    for rel in DELETE:
        (ROOT / rel).unlink()
    for rel, text in NEW_CSS.items():
        p = ROOT / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text, encoding="utf-8", newline="\n")
    for rel, text in edits.items():
        (ROOT / rel).write_text(text, encoding="utf-8", newline="\n")
    (ROOT / "tests" / "css-hygiene-qa.mjs").write_text(QA, encoding="utf-8", newline="\n")

    print("[OK] Sistema visual v2: 13 hojas en @layer, 0 !important")
    print("[OK] Eliminados theme, theme-romance, reset, shell y visual-system")
    print("[OK] Textos HUD reemplazados en test, perfil, Descubrir y Explorar")
    print("[OK] tests/css-hygiene-qa.mjs actualizado")
    print(f"[SAFE] Backup: {BACKUP.relative_to(ROOT)}")

if __name__ == "__main__":
    main()
